import type { Metadata } from "next";
import { site } from "@/lib/site/config";

/** Site-wide share image generated by app/opengraph-image.tsx. */
export const defaultShareImage = { url: "/opengraph-image", width: 1200, height: 630, alt: `${site.name} — pharmaceutical marketing and distribution` };

/** Site-wide social defaults; pages add their own title, description, path and (optionally) image. */
export const ogDefaults = {
  type: "website" as const,
  siteName: site.name,
  locale: "en_IN",
};

type PageMetaInput = {
  title: string;
  description: string;
  /** Path of the page, e.g. "/about"; becomes the canonical URL and og:url. */
  path: string;
  /**
   * Social image; the site-wide share image is used when omitted. Pass `null` for routes with their own
   * opengraph-image file — a config image would otherwise replace it.
   */
  image?: { url: string; width: number; height: number; alt: string } | null;
  robots?: Metadata["robots"];
};

/**
 * Title, description, canonical URL and matching Open Graph / Twitter tags for one page.
 * Next replaces (does not merge) a parent's `openGraph` object, so every page builds a complete one here.
 */
export function pageMeta({ title, description, path, image, robots }: PageMetaInput): Metadata {
  const fullTitle = `${title} | ${site.name}`;
  const images = image === null ? undefined : [image ?? defaultShareImage];
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { ...ogDefaults, title: fullTitle, description, url: path, ...(images && { images }) },
    twitter: { card: "summary_large_image", title: fullTitle, description, ...(images && { images: images.map((i) => i.url) }) },
    ...(robots && { robots }),
  };
}

/** Serialises JSON-LD safely for an inline <script> (no closing-tag injection). */
export const jsonLd = (data: unknown) => ({ __html: JSON.stringify(data).replace(/</g, "\\u003c") });
